def f(gin):
    h,w=len(gin),len(gin[0])
    out=[row[:] for row in gin]
    cs=comps(gin)
    lines={}  # (row,linecolor) and (col,linecolor)
    for cp in cs:
        nz=[(r,c,gin[r][c]) for r,c in cp if gin[r][c]!=3]
        if not nz: continue
        cr_,cc_,col=nz[0]
        # prefer center of plus; fallback: any non-3
        for j in range(w):
            if out[cr_][j]==0 and lines.get((cr_,j))!=col: lines[(cr_,j)]=col
        for i in range(h):
            if out[i][cc_]==0 and lines.get((i,cc_))!=col: lines[(i,cc_)]=col
    for key,val in lines.items():
        r,c=key
        # column line wins over row line at crossings
        if c<w and r<h:
            pass
        for j in range(w):
            if out[r][j]==0: out[r][j]=val
        for i in range(h):
