def find_centers(g):
    H,W=len(g),len(g[0]); seen=set(); res=[]
    pts={(r,c) for r in range(H) for c in range(W) if g[r][c]!=0}
    for p in sorted(pts):
        if p in seen: continue
        st=[p]; comp=[]; seen.add(p)
        while st:
            r,c=st.pop(); comp.append((r,c))
            for dr in(-1,0,1):
                for dc in(-1,0,1):
                    q=(r+dr,c+dc)
                    if q in pts and q not in seen:
                        seen.add(q); st.append(q)
        # center: the cell that is NOT 3 and is surrounded by 3s (in a 5-cell plus/diamond)
        # plus-shaped comps: exactly 5 cells forming a plus; center = the odd-colored one
        rs=sorted({r for r,c in comp}); cs=sorted({c for r,c in comp})
        hgt=max(rs)-min(rs)+1; wid=max(cs)-min(cs)+1
        if len(comp)==5 and max(hgt,wid)==3 and min(hgt,wid)==3:
            cr=(rs[1]+rs[2])/2; cc=(cs[1]+cs[2])/2
            res.append(((round(cr),round(cc)), collections.Counter(g[a][b] for a,b in comp)))
    return res

