        st=[p]; comp=[]; seen.add(p)
        while st:
            r,c=st.pop(); comp.append((r,c))
            for dr in(-1,0,1):
                for dc in(-1,0,1):
                    q=(r+dr,c+dc)
                    if q in pts and q not in seen:
                        seen.add(q); st.append(q)
        rs=sorted({r for r,c in comp}); cs=sorted({c for r,c in comp})
        hgt=max(rs)-min(rs); wid=max(cs)-min(cs)
        if len(comp)==5 and 0<hgt<=2 and 0<wid<=2:
